  var CONS = [["tch","च"],["chh","छ"],["sh","श"],["ch","च"],["th","थ"],["kh","ख"],["gh","घ"],["ph","फ"],["bh","भ"],["dh","ध"],["jh","झ"],["ck","क"],["ng","ंग"],["qu","क्व"],["ss","स"],["tt","ट"],["ll","ल"],["nn","न"],["mm","म"],["pp","प"],["rr","र"],["dd","ड"],["bb","ब"],["gg","ग"],["ff","फ"],["cc","क"],["kk","क"],["zz","ज"],["x","क्स"],["b","ब"],["c","क"],["d","ड"],["f","फ"],["g","ग"],["h","ह"],["j","ज"],["k","क"],["l","ल"],["m","म"],["n","न"],["p","प"],["q","क"],["r","र"],["s","स"],["t","ट"],["v","व"],["w","व"],["z","ज"]];
